  "content": "import typing

from tenacity import retry
from tenacity.wait import wait_base, WaitBaseT


def test_wait_callable_returns_int() -> None:
    @retry(wait=lambda retry_state: 10)
    def my_fn() -> None:
        pass

    my_fn()


def test_wait_base_subclass_returns_float() -> None:
    class MyWait(wait_base):
        def __call__(self, retry_state: "RetryCallState") -> float:
            return 1.0

    @retry(wait=MyWait())
    def my_fn() -> None:
        pass

    my_fn()
